func run(ctx):
    var names = ["Cube_A", "Cube_B", "Cube_C", "Cube_D", "Cube_E"]
    for i in range(5):
        ctx.add_mesh("box", names[i], null, {"size": Vector3(1, 1, 1), "position": Vector3(-4 + i * 2, 0.5, 0)})
    ctx.add_node("DirectionalLight3D", "Sun", null, {"rotation_degrees": Vector3(-50, 30, 0), "shadow_enabled": true})
    ctx.add_camera(Vector3(0, 6, 12), Vector3(0, 0.5, 0), true)
    var saved = ctx.save_scene()
    return {"saved": saved}
